// Extrair dados da mensagem recebida via Evolution API v2
const body = $input.item.json.body || $input.item.json;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};

// Ignorar mensagens enviadas pelo próprio bot/número (fromMe: true)
if (key.fromMe === true) {
  return [];
}

// Ignorar mensagens de grupos ou status broadcast
const remoteJid = key.remoteJid || '';
if (remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) {
  return [];
}

// Extrair número limpo
const phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
const pushName = data.pushName || 'Lead Interessado';

// Extrair texto da mensagem (texto simples, estendido ou transcrição)
let text = message.conversation || 
           message.extendedTextMessage?.text || 
           message.imageMessage?.caption ||
           message.videoMessage?.caption ||
           '';

if (!text && message.audioMessage) {
  text = '🎙️ [Áudio recebido]';
}

if (!text) {
  text = '📎 [Mídia / Arquivo recebido]';
}

return {
  json: {
    phone,
    pushName,
    text,
    timestamp: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
    whatsappLink: `https://wa.me/${phone}`
  }
};

